}
const p=motes.geometry.attributes.position;for(let i=0;i<moteCount;i++){p.array[i*3+1]+=.22*dt;p.array[i*3]+=(Math.sin(elapsed*.35+i)*.15)*dt;if(p.array[i*3+1]>18)p.array[i*3+1]=0}p.needsUpdate=true;gateLight.intensity=5.5+Math.sin(elapsed*1.4)*.5;sun.position.x=-95+Math.sin(elapsed*.018)*8;renderer.render(scene,camera)}requestAnimationFrame(animate);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight)});
setTimeout(()=>hint.classList.add('fade'),13000);
